import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Is Clash compatible with Shadowrocket?","description":"How to move Shadowrocket subscriptions, QR codes, node parameters, rules and module needs to Clash for iOS.","frontmatter":{"title":"Is Clash compatible with Shadowrocket?","description":"How to move Shadowrocket subscriptions, QR codes, node parameters, rules and module needs to Clash for iOS.","head":[["meta",{"name":"keywords","content":"Shadowrocket to Clash,Shadowrocket subscription,Shadowrocket nodes,Clash iOS"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Can I use a Shadowrocket subscription in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Yes when the provider returns mihomo YAML from an HTTPS subscription URL. Change the subscription User-Agent when necessary.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I use ss:// and other Shadowrocket node parameters in Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Organize standalone link or Base64 list parameters as mihomo YAML, or enter them in the node editor. A QR code can add an HTTPS subscription URL.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move Shadowrocket rules and modules?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Recreate the original rules, modules, rewrites and script needs with mihomo configuration, Clash rules and matching features.\\"}}]}"]]},"headers":[],"relativePath":"guide/compatibility/shadowrocket.md","filePath":"guide/compatibility/shadowrocket.md","lastUpdated":0}`),a={name:`guide/compatibility/shadowrocket.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="is-clash-compatible-with-shadowrocket" tabindex="-1">Is Clash compatible with Shadowrocket? <a class="header-anchor" href="#is-clash-compatible-with-shadowrocket" aria-label="Permalink to “Is Clash compatible with Shadowrocket?”">​</a></h1><p><strong>Subscriptions and common nodes continue to work, while the original routing experience can be recreated in Clash.</strong></p><p>If you already use a provider subscription in Shadowrocket and the provider returns mihomo YAML from an HTTPS URL, you can usually add the same subscription URL to Clash. The same server can be used when its protocol and parameters match.</p><h2 id="how-do-i-import-a-shadowrocket-subscription" tabindex="-1">How do I import a Shadowrocket subscription? <a class="header-anchor" href="#how-do-i-import-a-shadowrocket-subscription" aria-label="Permalink to “How do I import a Shadowrocket subscription?”">​</a></h2><ol><li>Copy the active subscription URL from Shadowrocket.</li><li>Add it as a remote configuration in Clash.</li><li>Update the profile and check its nodes and policy groups.</li><li>When the provider offers multiple formats, change the subscription User-Agent and select Clash / mihomo output.</li><li>Test latency, choose a node and connect.</li></ol><h2 id="how-to-use-share-links-and-qr-codes" tabindex="-1">How to use share links and QR codes <a class="header-anchor" href="#how-to-use-share-links-and-qr-codes" aria-label="Permalink to “How to use share links and QR codes”">​</a></h2><p>QR codes offer a quick way to add an HTTPS subscription URL that returns mihomo YAML. For <code>ss://</code>, <code>ssr://</code>, <code>vmess://</code>, <code>vless://</code>, <code>trojan://</code>, <code>hysteria2://</code>, <code>tuic://</code>, <code>anytls://</code> and Base64 node lists, organize the server, port, credentials, TLS and transport parameters as mihomo YAML, or add them in the node editor.</p><h2 id="what-to-recreate-in-clash" tabindex="-1">What to recreate in Clash <a class="header-anchor" href="#what-to-recreate-in-clash" aria-label="Permalink to “What to recreate in Clash”">​</a></h2><ul><li>express the original routing logic with Clash rules;</li><li>recreate module, rewrite and script needs with matching features;</li><li>set node groups and scenarios to match your workflow;</li><li>use Clash profile management and backup options for your setup.</li></ul><p>This keeps your existing nodes useful while giving the configuration a clear structure that matches Clash.</p><h2 id="use-standalone-node-parameters" tabindex="-1">Use standalone node parameters <a class="header-anchor" href="#use-standalone-node-parameters" aria-label="Permalink to “Use standalone node parameters”">​</a></h2><p>Inspect or export the node parameters in Shadowrocket, then recreate the node in Clash from its server, port, authentication, TLS, and transport parameters, or organize them as mihomo YAML.</p><h2 id="can-i-keep-using-the-same-server" tabindex="-1">Can I keep using the same server? <a class="header-anchor" href="#can-i-keep-using-the-same-server" aria-label="Permalink to “Can I keep using the same server?”">​</a></h2><p>The same server can work when Clash supports the protocol and the protocol version, transport, TLS, authentication and other parameters match.</p><p>Return to the <a href="/clash.md/guide/compatibility">compatibility overview</a>, or see <a href="/clash.md/guide/protocols">all supported protocols</a>.</p>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};